59: static BOOL RSUsable(UIView *v) {
60:     return v && v.window && !v.hidden && v.alpha>0.01 &&
61:            CGRectGetWidth(v.bounds)>=8 && CGRectGetWidth(v.bounds)<=64 &&
62:            CGRectGetHeight(v.bounds)>=8 && CGRectGetHeight(v.bounds)<=64;
63: }
64: static void RSTrack(UIView *v) {
65:     if (!v || !RSIsPortal(v)) return;
66:     if (!RSCandidates) RSCandidates=[NSHashTable weakObjectsHashTable];
67:     if (RSUsable(v)) [RSCandidates addObject:v];
68:     else { [RSCandidates removeObject:v]; if (RSPreferred==v) RSPreferred=nil; }
69: }
